 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Store each color's traced cells, so crossings can be marked afterward.
    traces = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # 1: two cells right, then one up.
                end = (r - 1, c + 2)
                path = [(r, x) for x in range(c + 1, c + 3)]
            elif color == 2:
                # 2: four cells left.
                end = (r, c - 4)
                path = [(r, x) for x in range(c - 3, c)]
            elif color == 3:
                # 3: three cells down.
                end = (r + 3, c)
                path = [(x, c) for x in range(r + 1, r + 3)]
            elif color == 6:
                # 6: six cells up.
                end = (r - 6, c)
                path = [(x, c) for x in range(r - 5, r)]
            else:
                continue
            er, ec = end
            if 0 <= er < h and 0 <= ec < w:
                for pr, pc in path:
                    if 0 <= pr < h and 0 <= pc < w:
                        if out[pr][pc] == 0:
                            out[pr][pc] = 5
                if color == 1:
                    # The path ends at the horizontal projection; the 1 is one row above.
                    if out[er][ec] == 0:
                        out[er][ec] = 1
                else:
                    if out[er][ec] == 0:
                        out[er][ec] = color
            traces.append((color, r, c, end, path))

    # 2's horizontal stroke crossing 3/6's vertical stroke makes a 4;
    # continue the diagonal 4 trail southwest to the grid edge.
    horizontal = set()
    vertical = set()
    for color, r, c, end, path in traces:
        if color == 2:
            horizontal.update([(r, c), end] + path)
        elif color in (3, 6):
            vertical.update([(r, c), end] + path)
    for r, c in horizontal & vertical:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == 0:
                out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
